55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    private final TelephoneNormalizer telephoneNormalizer;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper,
78	                                 TelephoneNormalizer telephoneNormalizer) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	        this.telephoneNormalizer = telephoneNormalizer;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        rejectBlankOwnerFields(ownerFieldsDto);
115	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
116	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
117	        }
118	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
119	        rejectDuplicateTelephone(normalizedTelephone);
120	        ownerFieldsDto.setTelephone(normalizedTelephone);
121	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        if (owner.getRegistrationDate() == null) {
125	            owner.setRegistrationDate(LocalDate.now());
126	        }
127	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
128	        this.clinicService.saveOwner(owner);
129	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
130	        headers.setLocation(UriComponentsBuilder.newInstance()
131	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
132	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
138	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
139	        if (currentOwner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        currentOwner.setAddress(ownerFieldsDto.getAddress());
143	        currentOwner.setCity(ownerFieldsDto.getCity());
144	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
145	        currentOwner.setLastName(ownerFieldsDto.getLastName());
146	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
147	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
148	        this.clinicService.saveOwner(currentOwner);
149	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Transactional
154	    @Override
155	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        this.clinicService.deleteOwner(owner);
161	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        HttpHeaders headers = new HttpHeaders();
172	        Pet pet = petMapper.toPet(petFieldsDto);
173	        owner.setId(ownerId);
174	        pet.setOwner(owner);
175	        pet.getType().setName(null);
176	        this.clinicService.savePet(pet);
177	        PetDto petDto = petMapper.toPetDto(pet);
178	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
179	            .buildAndExpand(pet.getId()).toUri());
180	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
186	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
187	        if (currentOwner != null) {
188	            Pet currentPet = this.clinicService.findPetById(petId);
189	            if (currentPet != null) {
190	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
191	                currentPet.setName(petFieldsDto.getName());
192	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
193	                this.clinicService.savePet(currentPet);
194	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
195	            }
196	        }
197	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
203	        HttpHeaders headers = new HttpHeaders();
204	        Visit visit = visitMapper.toVisit(visitFieldsDto);
205	        Pet pet = new Pet();
206	        pet.setId(petId);
207	        visit.setPet(pet);
208	        this.clinicService.saveVisit(visit);
209	        VisitDto visitDto = visitMapper.toVisitDto(visit);
210	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
211	            .buildAndExpand(visit.getId()).toUri());
212	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
213	    }
214	
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner != null) {
221	            Pet pet = owner.getPet(petId);
222	            if (pet != null) {
223	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
228	
229	    /**
230	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
231	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
232	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
233	     * blank (e.g. {@code "   "}). The offending field names are reported through an
234	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
235	     * as a 400 response carrying an {@code errors} array of field names.
236	     *
237	     * @param ownerFieldsDto the submitted owner fields
238	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
239	     */
240	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
241	        List<String> blankFields = new ArrayList<>();
242	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
243	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
244	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
245	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
246	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
247	        if (!blankFields.isEmpty()) {
248	            throw new InvalidOwnerFieldsException(blankFields);
249	        }
250	    }
251	
252	    private void addIfBlank(List<String> blankFields, String field, String value) {
253	        if (value != null && value.isBlank()) {
254	            blankFields.add(field);
255	        }
256	    }
257	
258	    /**
259	     * Normalizes an owner's optional email address. When present it is stored and returned
260	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
261	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
262	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
263	     * method runs.
264	     *
265	     * @param email the raw email value from the request, or {@code null} when omitted
266	     * @return the lower-cased email, or {@code null} when none was supplied
267	     */
268	    private String normalizeEmail(String email) {
269	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
270	    }
271	
272	    /**
273	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
274	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
275	     * owner's {@code lastName}, and {@code NNNN} is a global 4-digit zero-padded sequence equal
276	     * to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
277	     *
278	     * @param lastName the last name of the owner being created
279	     * @return the formatted customer code
280	     */
281	    private String nextCustomerCode(String lastName) {
282	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
283	        long sequence = this.clinicService.findAllOwners().size() + 1L;
284	        return String.format("%s-%04d", last3, sequence);
285	    }
286	
287	    /**
288	     * Rejects a create request whose normalized telephone is already used by any existing owner.
289	     * Existing owners' telephones are reduced to the same canonical form (via
290	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
291	     * only in formatting still collide. A collision is reported through a
292	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
293	     * as a 409 Conflict response.
294	     *
295	     * @param normalizedTelephone the canonical telephone of the owner being created
296	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
297	     */
298	    private void rejectDuplicateTelephone(String normalizedTelephone) {
299	        boolean duplicate = existingOwnerMatches(
300	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
301	            normalizedTelephone);
302	        if (duplicate) {
303	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
304	        }
305	    }
306	
307	    /**
308	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
309	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
310	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
311	     * and the owner being created to the same canonical key and reject a match.
312	     *
313	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
314	     * @param key the canonical key of the owner being created
315	     * @return {@code true} if some existing owner shares the key
316	     */
317	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
318	        return this.clinicService.findAllOwners().stream()
319	            .map(keyExtractor)
320	            .filter(Objects::nonNull)
321	            .anyMatch(key::equals);
322	    }
323	
324	    /**
325	     * Rejects a create request that shares a household with an existing owner: another owner already
326	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
327	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
328	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
329	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
330	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
331	     * check when the request opts in via {@code sharesHousehold}.
332	     *
333	     * @param lastName the last name of the owner being created
334	     * @param address the address of the owner being created
335	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
336	     */
337	    private void rejectDuplicateHousehold(String lastName, String address) {
338	        String canonicalLastName = canonicalizeHousehold(lastName);
339	        String canonicalAddress = canonicalizeHousehold(address);
340	        if (canonicalLastName == null || canonicalAddress == null) {
341	            return;
342	        }
343	        boolean duplicate = this.clinicService.findAllOwners().stream()
344	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
345	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
346	        if (duplicate) {
347	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
348	        }
349	    }
350	
351	    /**
352	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
353	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
354	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
355	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
356	     *
357	     * @param value the raw field value, or {@code null}
358	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
359	     */
360	    private String canonicalizeHousehold(String value) {
361	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
362	    }
363	}
